public int visitFrameStart(final int offset, final int numLocal, final int numStack) {

    // Check if the current frame is null
    if (currentFrame == null) {
        throw new IllegalStateException("Current frame is null");
    }

    // Check if the offset is valid
    if (offset < 0) {
        throw new IllegalArgumentException("Offset must be non-negative");
    }

    // Check if the number of local variables is valid
    if (numLocal < 0) {
        throw new IllegalArgumentException("Number of local variables must be non-negative");
    }

    // Check if the number of stack elements is valid
    if (numStack < 0) {
        throw new IllegalArgumentException("Number of stack elements must be non-negative");
    }

    // Set the current frame's offset, number of local variables, and number of stack elements
    currentFrame.setOffset(offset);
    currentFrame.setNumLocal(numLocal);
    currentFrame.setNumStack(numStack);

    // Return the index of the next element to be written in this frame
    return currentFrame.getNextElementIndex();
}

private void enlarge(final int size) {
    if (size < 0) {
        throw new IllegalArgumentException("Size must be non-negative");
    }
    if (size == 0) {
        return;
    }
    int newCapacity = Math.max(this.capacity + size, this.capacity * 2);
    byte[] newData = new byte[newCapacity];
    System.arraycopy(this.data, 0, newData, 0, this.capacity);
    this.data = newData;
    this.capacity = newCapacity;
}

