public static <V, E> IsomorphicGraphMapping<V, E> identity(Graph<V, E> graph) {
    // Create a new mapping from the input graph to itself
    IsomorphicGraphMapping<V, E> mapping = new IsomorphicGraphMapping<>(graph, graph);

    // Iterate over the vertices in the input graph
    for (V vertex : graph.vertices()) {
        // Add a mapping from the vertex to itself
        mapping.addMapping(vertex, vertex);
    }

    // Iterate over the edges in the input graph
    for (E edge : graph.edges()) {
        // Add a mapping from the edge to itself
        mapping.addMapping(edge, edge);
    }

    return mapping;
}

