@Override
public void generateGraph(Graph<V, E> target, Map<String, V> resultMap) {
    // Check if the target graph is null
    if (target == null) {
        throw new IllegalArgumentException("Target graph cannot be null");
    }

    // Check if the result map is null
    if (resultMap == null) {
        throw new IllegalArgumentException("Result map cannot be null");
    }

    // Check if the result map is empty
    if (resultMap.isEmpty()) {
        throw new IllegalArgumentException("Result map cannot be empty");
    }

    // Create a new bipartite graph
    Graph<V, E> bipartiteGraph = new Graph<V, E>();

    // Add vertices to the bipartite graph
    for (Map.Entry<String, V> entry : resultMap.entrySet()) {
        bipartiteGraph.addVertex(entry.getValue());
    }

    // Add edges to the bipartite graph
    for (Map.Entry<String, V> entry : resultMap.entrySet()) {
        V sourceVertex = entry.getValue();
        for (Map.Entry<String, V> otherEntry : resultMap.entrySet()) {
            V targetVertex = otherEntry.getValue();
            if (!sourceVertex.equals(targetVertex)) {
                bipartiteGraph.addEdge(sourceVertex, targetVertex);
            }
        }
    }

    // Set the bipartite graph as the target graph
    target.setGraph(bipartiteGraph);
}

