protected void subAppend(LoggingEvent event) {
    // Check if the event is valid
    if (event == null) {
        throw new IllegalArgumentException("Event cannot be null");
    }

    // Check if the event has a message
    if (event.getMessage() == null) {
        throw new IllegalArgumentException("Event message cannot be null");
    }

    // Check if the event has a level
    if (event.getLevel() == null) {
        throw new IllegalArgumentException("Event level cannot be null");
    }

    // Check if the event has a timestamp
    if (event.getTimeStamp() == null) {
        throw new IllegalArgumentException("Event timestamp cannot be null");
    }

    // Check if the event has a thread name
    if (event.getThreadName() == null) {
        throw new IllegalArgumentException("Event thread name cannot be null");
    }

    // Check if the event has a logger name
    if (event.getLoggerName() == null) {
        throw new IllegalArgumentException("Event logger name cannot be null");
    }

    // Check if the event has a throwable
    if (event.getThrowable() == null) {
        throw new IllegalArgumentException("Event throwable cannot be null");
    }

    // Check if the event has a throwable message
    if (event.getThrowable().getMessage() == null) {
        throw new IllegalArgumentException("Event throwable message cannot be null");
    }

    // Check if the event has a throwable stack trace
    if (event.getThrowable().getStackTrace() == null) {
        throw new IllegalArgumentException("Event throwable stack trace cannot be null");
    }

    // Write the event to the log file
    try {
        // Create a new log file if it doesn't exist
        File logFile = new File("log.txt");
        if (!logFile.exists()) {
            logFile.createNewFile();
        }

        // Write the event to the log file
        FileWriter writer = new FileWriter(logFile, true);
        writer.write(event.getMessage());
        writer.write("\n");
        writer.write(event.getLevel().toString());
        writer.write("\n");
        writer.write(event.getTimeStamp().toString());
        writer.write("\n");
        writer.write(event.getThreadName());
        writer.write("\n");
        writer.write(event.getLoggerName());
        writer.write("\n");
        writer.write(event.getThrowable().getMessage());
        writer.write("\n");
        writer.write(event.getThrowable().getStackTrace().toString());
        writer.write("\n");
        writer.close();
    } catch (IOException e) {
        e.printStackTrace();
    }
}

