public long readLong(final int offset) {
    // Check if the offset is valid
    if (offset < 0 || offset >= this.data.length) {
        throw new IndexOutOfBoundsException("Offset is out of bounds: " + offset);
    }

    // Read the long value at the given offset
    long value = 0;
    for (int i = 0; i < 8; i++) {
        value |= (long) this.data[offset + i] << (8 * i);
    }

    return value;
}

@Override
public boolean equals(final byte[] data, int offset, final int len) {

// Step 1: Check if the input array is null
if (data == null) {
return false;
}

// Step 2: Check if the offset and length are valid
if (offset < 0 || len < 0 || offset + len > data.length) {
return false;
}

// Step 3: Check if the internal array and the input array have the same length
if (this.data.length != len) {
return false;
}

// Step 4: Check if the contents of the internal array and the input array match
for (int i = 0; i < len; i++) {
if (this.data[i] != data[offset + i]) {
return false;
}
}

// Step 5: If all checks pass, return true
return true;
}

