public static long compressTimeBucket(long timeBucket, int dayStep) {
    if (dayStep < 1) {
        throw new IllegalArgumentException("dayStep must be greater than or equal to 1");
    }
    if (timeBucket < 0) {
        throw new IllegalArgumentException("timeBucket must be greater than or equal to 0");
    }
    long days = timeBucket / 1000000;
    long remainder = timeBucket % 1000000;
    long step = dayStep * 1000000;
    long newDays = days / dayStep * dayStep;
    long newRemainder = remainder % step;
    return newDays * 1000000 + newRemainder;
}

public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
  if (str == null) {
    throw new IllegalArgumentException("CharSequence cannot be null");
  }
  if (index < 0 || index >= str.length()) {
    throw new IllegalArgumentException("Index out of bounds");
  }
  if (len < 0 || len > str.length() - index) {
    throw new IllegalArgumentException("Length out of bounds");
  }

  int size = 0;
  for (int i = index; i < index + len; i++) {
    char c = str.charAt(i);
    if (c <= 0x7F) {
      size += 1;
    } else if (c <= 0x7FF) {
      size += 2;
    } else if (Character.isHighSurrogate(c)) {
      size += 4;
      i++;
    } else {
      size += 3;
    }
  }
  return size;
}

