  if (!contains(val)) {
    return false;
  }
  for (int i = 0; i < size; i++) {
    if (values[i] == val) {
      for (int j = i; j < size - 1; j++) {
        values[j] = values[j + 1];
      }
      size--;
      return true;
    }
  }
  return false;
}

