    int numTypes = 0;
    for (int i = 0; i < descriptor.length(); i++) {
        char c = descriptor.charAt(i);
        if (c == '(') {
            numTypes++;
        } else if (c == ')') {
            numTypes--;
        } else if (c == 'L') {
            numTypes++;
        }
    }

    // Step 2: Pop the types from the output frame stack.
    for (int i = 0; i < numTypes; i++) {
        pop();
    }
}

