    }

    // Add the edge to the index
    if (!index.containsKey(sourceVertex)) {
        index.put(sourceVertex, new HashSet<V>());
    }
    index.get(sourceVertex).add(targetVertex);

    // Add the edge to the reverse index
    if (!reverseIndex.containsKey(targetVertex)) {
        reverseIndex.put(targetVertex, new HashSet<V>());
    }
    reverseIndex.get(targetVertex).add(sourceVertex);
}

