private void putAbstractTypes(final int start, final int end) {
    // Check if the input parameters are valid
    if (start < 0 || start >= currentFrame.length || end < 0 || end > currentFrame.length || start > end) {
        throw new IllegalArgumentException("Invalid input parameters");
    }

    // Iterate over the types in the current frame
    for (int i = start; i < end; i++) {
        // Get the type at the current index
        Type type = currentFrame[i];

        // Check if the type is a reference type
        if (type instanceof ReferenceType) {
            // If it is a reference type, get the corresponding JVMS verification_type_info
            VerificationTypeInfo verificationTypeInfo = getVerificationTypeInfo((ReferenceType) type);

            // Add the verification type info to the stack map table entries
            stackMapTableEntries.add(verificationTypeInfo);
        } else {
            // If the type is not a reference type, add it to the stack map table entries as is
            stackMapTableEntries.add(type);
        }
    }
}

