public final byte[] toByteArray() {
  // Check if the buffer is empty
  if (buffer.isEmpty()) {
    return new byte[0];
  }

  // Calculate the total size of the buffer
  int totalSize = 0;
  for (ByteBuffer buffer : buffers) {
    totalSize += buffer.remaining();
  }

  // Create a new byte array to hold the contents of the buffer
  byte[] bytes = new byte[totalSize];

  // Copy the contents of each buffer into the byte array
  int offset = 0;
  for (ByteBuffer buffer : buffers) {
    int remaining = buffer.remaining();
    buffer.get(bytes, offset, remaining);
    offset += remaining;
  }

  return bytes;
}

public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }
    StringBuilder sb = new StringBuilder();
    for (int i = 0; i < str.length(); i++) {
        char c = str.charAt(i);
        if (c == '\\') {
            if (i + 1 < str.length()) {
                char nextChar = str.charAt(i + 1);
                if (nextChar == 'n') {
                    sb.append('\n');
                    i++;
                } else if (nextChar == 'r') {
                    sb.append('\r');
                    i++;
                } else if (nextChar == 't') {
                    sb.append('\t');
                    i++;
                } else if (nextChar == 'b') {
                    sb.append('\b');
                    i++;
                } else if (nextChar == 'f') {
                    sb.append('\f');
                    i++;
                } else if (nextChar == '\\') {
                    sb.append('\\');
                    i++;
                } else if (nextChar == '\'') {
                    sb.append('\'');
                    i++;
                } else if (nextChar == '\"') {
                    sb.append('\"');
                    i++;
                } else {
                    throw new Exception("Invalid escape sequence: \\" + nextChar);
                }
            } else {
                throw new Exception("Invalid escape sequence: \\");
            }
        } else {
            sb.append(c);
        }
    }
    return sb.toString();
}

private static String javaCharset(String charset) {
    if (charset == null || charset.isEmpty()) {
        throw new IllegalArgumentException("Charset cannot be null or empty");
    }
    String javaCharset = null;
    switch (charset.toLowerCase()) {
        case "us-ascii":
            javaCharset = "US-ASCII";
            break;
        case "iso-8859-1":
            javaCharset = "ISO-8859-1";
            break;
        case "utf-8":
            javaCharset = "UTF-8";
            break;
        case "utf-16":
            javaCharset = "UTF-16";
            break;
        case "utf-16be":
            javaCharset = "UTF-16BE";
            break;
        case "utf-16le":
            javaCharset = "UTF-16LE";
            break;
        default:
            throw new IllegalArgumentException("Unsupported charset: " + charset);
    }
    return javaCharset;
}

