    if (offset < 0 || offset >= this.data.length) {
        throw new IndexOutOfBoundsException("Offset is out of bounds: " + offset);
    }

    // Read the short value at the given offset
    short value = this.data[offset];

    // Check if the value is negative
    if (value < 0) {
        // If the value is negative, it is stored as a two's complement
        value = (short) (value & 0xFFFF);
    }

    return value;
}

public static Object copyArrayGrow1(final Object array, final Class<?> newArrayComponentType) {

    // Check if the input array is null
    if (array == null) {
        // If the input array is null, create a new array of size 1 with the given component type
        return Array.newInstance(newArrayComponentType, 1);
    }

    // Get the length of the input array
    int length = Array.getLength(array);

    // Create a new array of the same type and length + 1
    Object newArray = Array.newInstance(array.getClass().getComponentType(), length + 1);

    // Copy the elements from the input array to the new array
    System.arraycopy(array, 0, newArray, 0, length);

    // Set the last element of the new array to the default value
    Array.set(newArray, length, null);

    return newArray;
}

