private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {

    // Initialize the circulator to the start node
    OuterFaceCirculator circulator = new OuterFaceCirculator(start, dir);

    // Iterate through the nodes on the outer face
    while (circulator.hasNext()) {
        Node currentNode = circulator.next();

        // Check if the current node satisfies the predicate
        if (predicate.test(currentNode)) {
            // If the current node satisfies the predicate, return a circulator to it
            return new OuterFaceCirculator(currentNode, dir);
        }

        // If the current node is the stop node, return a circulator to it
        if (currentNode == stop) {
            return new OuterFaceCirculator(currentNode, dir);
        }
    }

    // If no node satisfies the predicate and the stop node is not reached, return a circulator to the start node
    return new OuterFaceCirculator(start, dir);
}

