public final MatchResult match(CharSequence uri) {
    // Check if the URI is null or empty
    if (uri == null || uri.length() == 0) {
        return null;
    }

    // Check if the URI matches the pattern
    if (uri.toString().matches(pattern)) {
        // Extract the matched groups
        Matcher matcher = pattern.matcher(uri);
        if (matcher.find()) {
            // Create a new MatchResult object
            MatchResult result = new MatchResult();
            result.setUri(uri);
            result.setMatchedGroups(matcher.groupCount());
            for (int i = 0; i < matcher.groupCount(); i++) {
                result.setGroup(i, matcher.group(i));
            }
            return result;
        }
    }

    // No match found, return null
    return null;
}

