  int extensionIndex = filename.lastIndexOf('.');
  if (extensionIndex > lastSeparatorIndex) {
    return extensionIndex;
  } else {
    return -1;
  }
}

public boolean isExpired(long timestamp, long expiredThreshold) {
    if (timestamp < 0 || expiredThreshold < 0) {
        throw new IllegalArgumentException("Timestamp and expiredThreshold must be non-negative");
    }
    return (System.currentTimeMillis() - timestamp) > expiredThreshold;
}

public Edge edgeToNext() {
    // Check if the current node is virtual
    if (isVirtual()) {
        // If the current node is virtual, return the edge from its real counterpart to the next node
        return getRealNode().getEdgeToNext();
    } else {
        // If the current node is real, return the edge from it to the next node
        return getEdgeToNext();
    }
}

public static boolean substringMatch(CharSequence str, int index, CharSequence substring) {
  if (str == null || substring == null) {
    return false;
  }
  if (index < 0 || index >= str.length()) {
    return false;
  }
  if (substring.length() > str.length() - index) {
    return false;
  }
  for (int i = 0; i < substring.length(); i++) {
    if (str.charAt(index + i) != substring.charAt(i)) {
      return false;
    }
  }
  return true;
}

protected void append(LoggingEvent event) {
    for (Client client : clients) {
        try {
            client.write(event.getMessage());
        } catch (IOException e) {
            e.printStackTrace();
        }
    }
}

public static String toString(final char ch) {
    if (ch < 0 || ch > 127) {
        throw new IllegalArgumentException("The character must be between 0 and 127");
    }
    return String.valueOf(ch);
}

private void checkIfPackedField() throws IOException {
    if (isPackedField()) {
        // If the field is packed, update the internal state to reflect that packed fields are being read
        setPackedFieldsRead(true);
    }
}

public int readTag() throws IOException {
  if (mInput.available() == 0) {
    return 0;
  }
  int tag = mInput.read();
  if (tag == -1) {
    throw new EOFException("Unexpected EOF while reading tag");
  }
  return tag;
}

public final ByteVector put11(final int byteValue1, final int byteValue2) {
    if (byteValue1 < 0 || byteValue1 > 255 || byteValue2 < 0 || byteValue2 > 255) {
        throw new IllegalArgumentException("Byte values must be between 0 and 255");
    }
    if (this.data.length < this.length + 2) {
        this.enlarge(2);
    }
    this.data[this.length++] = (byte) byteValue1;
    this.data[this.length++] = (byte) byteValue2;
    return this;
}

private String buildContentRange() {
    // Calculate the start and end indices of the range
    int startIndex = (currentPage - 1) * itemsPerPage;
    int endIndex = Math.min(startIndex + itemsPerPage - 1, totalItems - 1);

    // Build the 'Content-Range' value
    return String.format("items %d-%d/%d", startIndex, endIndex, totalItems);
}

public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
        List<ThreadSnapshot> threadSnapshots = new ArrayList<>();
        try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
            String line;
            while ((line = reader.readLine()) != null) {
                ThreadSnapshot threadSnapshot = parseThreadSnapshot(line);
                if (threadSnapshot != null && isInTimeRange(threadSnapshot, timeRanges)) {
                    threadSnapshots.add(threadSnapshot);
                }
            }
        }
        return threadSnapshots;
    }
